#include <sstream>
#include <string>
#include <vector>

const std::vector<std::string> nombres_grupos{"red", "green", "blue"};

bool buscar_grupo(const std::string& nombre, int& destino) {
    for (int id = 0; id < 3; ++id) {
        if (nombres_grupos.at(id) == nombre) {
            destino = id;
            return true;
        }
    }
    return false;
}

bool nombre_grupo(int id, std::string& destino) {
    if (id < 0 || id >= 3) {
        return false;
    }
    destino = nombres_grupos.at(id);
    return true;
}

int main() {
    for (const std::string& original : nombres_grupos) {
        int id{-1};
        std::string recuperado{"previous"};
        bool encontrado = buscar_grupo(original, id);
        bool convertido = false;
        if (encontrado) { convertido = nombre_grupo(id, recuperado); }
        std::cout << original << ':' << encontrado << ':'
                  << convertido << ':' << (recuperado == original) << '\n';
    }
    int id{8};
    bool encontrado = buscar_grupo("gray", id);
    std::string nombre{"previous"};
    bool convertido = nombre_grupo(-1, nombre);
    std::cout << encontrado << ':' << id << ':' << convertido << ':' << nombre;
    return 0;
}
